      !(value.snapshot === null || typeof value.snapshot === 'string')) return null;
  const names: string[] = value.names;
  const rounds: Match[][] = [];
  for (let r = 0; r < value.rounds.length; r++) {
    const input: unknown = value.rounds[r];
    if (!Array.isArray(input) || input.length !== names.length / 2 ** (r + 1)) return null;
    const round: Match[] = [];
    for (const item of input) {
      if (!isJsonObject(item) || !Array.isArray(item.players) || item.players.length !== 2 ||
        !item.players.every((p: unknown) => p === null || (isNonnegativeSafeInteger(p) && p < names.length)) ||
        !Array.isArray(item.scores) || item.scores.length !== 2 ||
        !item.scores.every((s: unknown) => s === null || isScore(s)) ||
        !(item.winner === null || (isNonnegativeSafeInteger(item.winner) && item.players.includes(item.winner))) ||
        !(item.boardCode === null || (typeof item.boardCode === 'string' && parseBoardCode(item.boardCode)))) return null;
      round.push({ players: [item.players[0], item.players[1]], scores: [item.scores[0], item.scores[1]], winner: item.winner, boardCode: item.boardCode });
    }
    rounds.push(round);
  }
  const round = value.rounds[value.round];
  if (!Array.isArray(round) || value.match >= round.length) return null;
  const phase = value.phase;
  if (phase !== 'ready' && phase !== 'playing' && phase !== 'turnDone' && phase !== 'matchDone' && phase !== 'complete') return null;
  const data: TournamentData = { version: 1, names, rounds, round: value.round, match: value.match, turn: value.turn, phase, snapshot: value.snapshot };
  const match = currentMatch(data);
  if (match.players.some((p) => p === null) || (phase === 'playing' && (!match.boardCode || !data.snapshot)) ||
    (phase === 'turnDone' && (!match.scores[0] || data.turn !== 0)) ||
    ((phase === 'matchDone' || phase === 'complete') && match.winner === null)) return null;
  if (data.snapshot) {
    const game = decodeSnapshot(data.snapshot);
    if (!game || game.boardCode !== match.boardCode || phase !== 'playing') return null;
  }
  return data;
}
