    if (!data || data.phase !== 'complete') return;
    setHistory((old) => {
      if (old.some((item) => JSON.stringify(item) === JSON.stringify(data))) return old;
      const next = [data, ...old];
      try { localStorage.setItem(HISTORY_KEY, JSON.stringify(next)); } catch { /* Storage can be unavailable. */ }
      return next;
    });
  }, [data]);

  function start(): void {
    const players = names.slice(0, count).map((name) => name.trim());
    if (players.some((name) => !name)) { setNotice('Enter a name for every player.'); return; }
    setNotice('');
    setData(createTournament(players));
  }
  function startTurn(): void {
    if (!data || !match) return;
    const boardCode = match.boardCode ?? freshBoardCode(size);
    setNotice('');
    setData({ ...updateMatch(data, { ...match, boardCode }), phase: 'playing', snapshot: null });
  }
  function finished(score: Score): void {
    setData((old) => {
      if (!old || old.phase !== 'playing') return old;
      const next = recordScore(old, score);
      if (next.phase === 'ready') setNotice('The scores are tied. Play the match again on a new deal.');
      return next.phase === 'matchDone' && next.round === next.rounds.length - 1
        ? { ...next, phase: 'complete' } : next;
    });
  }
  function exportTournament(): void {
    if (!data) {
      setJson(JSON.stringify({ version: 1, setup: true, count, names }, null, 2));
    } else {
      const snapshot = data.phase === 'playing' ? turn.current?.exportSnapshot() : null;
      if (data.phase === 'playing' && !snapshot) { setNotice('The turn is still starting. Try again.'); return; }
      setJson(JSON.stringify({ ...data, snapshot: snapshot ?? null }, null, 2));
    }
    setNotice('Tournament exported to the Tournament JSON box.');
  }
  function loadTournament(): void {
    const loaded = readTournament(json);
    if (loaded) { setData(loaded); setNotice('Tournament loaded.'); return; }
    try {
      const setup: unknown = JSON.parse(json);
      if (typeof setup === 'object' && setup !== null && 'version' in setup && setup.version === 1 &&
        'setup' in setup && setup.setup === true && 'count' in setup && (setup.count === 4 || setup.count === 8) &&
        'names' in setup && Array.isArray(setup.names) && setup.names.length === 8 &&
        setup.names.every((name: unknown) => typeof name === 'string' && name.length <= 100)) {
        setNames(setup.names); setCount(setup.count); setData(null); setNotice('Tournament setup loaded.'); return;
      }
    } catch { /* Show the same message for all invalid input. */ }
    setNotice('Invalid tournament JSON.');
  }
  return (
    <main className="tournament">
      <header><p className="eyebrow">A little focus. A perfect pair.</p><h1>Tournament</h1></header>
      {!data ? <>
        <p>Share one device and play the same deal in each match. Fewer moves wins; time breaks a tie. If both are equal, replay the match.</p>
        <div className="tournament-setup">
          <label htmlFor="players">Players</label>
          <select id="players" className="control" value={count} onChange={(event) => setCount(Number(event.currentTarget.value))}>
            <option value={4}>4</option><option value={8}>8</option>
          </select>
          <div className="player-inputs">{names.slice(0, count).map((name, index) => <div key={index}>
            <label htmlFor={`player-${index}`}>Player {index + 1}</label>
            <input id={`player-${index}`} className="control" value={name} maxLength={100} onChange={(event) => {
              const value = event.currentTarget.value;
              setNames((old) => old.map ( (item, i) => i === index ? value : item));
            }} />
          </div>)}</div>
          <p>Board size: {size}x{size}</p>
          <div className="tournament-actions"><button className="control" onClick={start}>Start tournament</button><button className="control" onClick={back}>Back to game</button></div>
        </div>
        <section><h2>Past tournaments</h2>{history.length === 0 ? <p>No finished tournaments yet.</p> : <ul>{history.map((item, index) => <li key={index}>
          <button className="control" onClick={() => { setData(item); setNotice(''); }}>Champion: {item.names[currentMatch(item).winner ?? 0]}</button>
        </li>)}</ul>}</section>
      </> : <>
        {data.phase === 'complete' ? <><h2>Champion: {data.names[match?.winner ?? 0]}</h2><button className="control" onClick={back}>Back to game</button></> : <>
          <p className="now-playing">Now playing: {data.names[match?.players[data.turn] ?? 0]}</p>
          <div className="tournament-actions">
            {data.phase === 'ready' && <button className="control" onClick={startTurn}>Start turn</button>}
            {data.phase === 'turnDone' && <button className="control" onClick={() => setData({ ...data, turn: 1, phase: 'ready' })}>Next turn</button>}
            {data.phase === 'matchDone' && <button className="control" onClick={() => setData(advanceMatch(data))}>Next match</button>}
            <button className="control" onClick={() => { setData(null); setNotice('Tournament ended.'); }}>Leave tournament</button>
          </div>
          {data.phase === 'playing' && match?.boardCode && <TournamentTurn key={`${data.round}-${data.match}-${data.turn}`} code={match.boardCode} snapshot={data.snapshot} finished={finished} ref={turn} />}
        </>}
        <section><h2>Bracket</h2><div className="bracket">{data.rounds.map((round, r) => <div className="bracket-round" key={r}>
          <h3>{r === data.rounds.length - 1 ? 'Final' : `Round ${r + 1}`}</h3>
          {round.map((item, m) => <div className="bracket-match" key={m}><h4>Match {m + 1}</h4>
            {item.players.map((player, p) => <p key={p}>{player === null ? 'To be decided' : data.names[player]}: {item.scores[p] ? `${item.scores[p]?.moves} moves, ${formatElapsed(item.scores[p]?.elapsedMs ?? 0)}` : '—'}</p>)}
            <p>Winner: {item.winner === null ? '—' : data.names[item.winner]}</p>
          </div>)}
        </div>)}</div></section>
      </>}
      <section className="tournament-transfer"><h2>Tournament JSON</h2>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea id="tournament-json" className="control" value={json} onChange={(event) => setJson(event.currentTarget.value)} rows={6} />
        <div className="tournament-actions"><button className="control" onClick={exportTournament}>Export tournament</button><button className="control" onClick={loadTournament}>Load tournament</button></div>
      </section>
      <p role="status" aria-live="polite">{notice}</p>
    </main>
  );
}
