    setData((old) => {
      if (!old || old.phase !== 'playing') return old;
      const next = recordScore(old, score);
      if (next.phase === 'ready') setNotice('The scores are tied. Play the match again on a new deal.');
      return next.phase === 'matchDone' && next.round === next.rounds.length - 1
        ? { ...next, phase: 'complete' } : next;
    });
  }
