        <section><h2>Bracket</h2><div className="bracket">{data.rounds.map((round, r) => <div className="bracket-round" key={r}>
          <h3>{r === data.rounds.length - 1 ? 'Final' : `Round ${r + 1}`}</h3>
          {round.map((item, m) => <div className="bracket-match" key={m}><h4>Match {m + 1}</h4>
            {item.players.map((player, p) => <p key={p}>{player === null ? 'To be decided' : data.names[player]}: {item.scores[p] ? `${item.scores[p]?.moves} moves, ${formatElapsed(item.scores[p]?.elapsedMs ?? 0)}` : '—'}</p>)}
