import { parseBoardCode } from '../deck.ts';
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { decodeSnapshot } from '../snapshot.ts';
import { isJsonObject, isNonnegativeSafeInteger, parseJson } from '../saved-format.ts';

export interface Score {
  moves: number;
  elapsedMs: number;
}
export interface Match {
  players: [number | null, number | null];
  scores: [Score | null, Score | null];
  winner: number | null;
  boardCode: string | null;
}
export type Phase = 'ready' | 'playing' | 'turnDone' | 'matchDone' | 'complete';
export interface TournamentData {
  version: 1;
  names: string[];
  rounds: Match[][];
  round: number;
  match: number;
  turn: number;
  phase: Phase;
  snapshot: string | null;
}

export function createTournament(names: string[]): TournamentData {
  const rounds: Match[][] = [];
  for (let count = names.length / 2; count >= 1; count /= 2) {
    rounds.push(
      Array.from({ length: count }, (_, index) => ({
        players: rounds.length === 0 ? [index * 2, index * 2 + 1] : [null, null],
        scores: [null, null],
        winner: null,
        boardCode: null,
      })),
    );
  }
  return { version: 1, names, rounds, round: 0, match: 0, turn: 0, phase: 'ready', snapshot: null };
}

export function currentMatch(data: TournamentData): Match {
  const match = data.rounds[data.round]?.[data.match];
  if (!match) throw new Error('Invalid tournament position.');
  return match;
}

export function updateMatch(data: TournamentData, match: Match): TournamentData {
  return {
    ...data,
    rounds: data.rounds.map((round, r) =>
      r === data.round ? round.map((item, m) => (m === data.match ? match : item)) : round,
    ),
  };
}

export function recordScore(data: TournamentData, score: Score): TournamentData {
  const match = currentMatch(data);
  const scores: [Score | null, Score | null] =
    data.turn === 0 ? [score, null] : [match.scores[0], score];
  if (data.turn === 0)
    return { ...updateMatch(data, { ...match, scores }), phase: 'turnDone', snapshot: null };
  const first = scores[0];
  if (!first) throw new Error('Missing first score.');
  const comparison = first.moves - score.moves || first.elapsedMs - score.elapsedMs;
  if (comparison === 0)
    return {
      ...updateMatch(data, { ...match, scores: [null, null], boardCode: null }),
      phase: 'ready',
      turn: 0,
      snapshot: null,
    };
  const winner = match.players[comparison < 0 ? 0 : 1];
  if (winner === null) throw new Error('Missing player.');
  return { ...updateMatch(data, { ...match, scores, winner }), phase: 'matchDone', snapshot: null };
}

export function advanceMatch(data: TournamentData): TournamentData {
  const winner = currentMatch(data).winner;
  if (winner === null) throw new Error('Missing winner.');
  if (data.round === data.rounds.length - 1) return { ...data, phase: 'complete' };
  const nextRound = data.round + 1;
  const nextMatch = Math.floor(data.match / 2);
  const rounds = data.rounds.map((round, r) =>
    r !== nextRound
      ? round
      : round.map((match, m) => {
          if (m !== nextMatch) return match;
          const players: [number | null, number | null] = [...match.players];
          players[data.match % 2] = winner;
          return { ...match, players };
        }),
  );
  const atEnd = data.match + 1 === data.rounds[data.round]?.length;
  return {
    ...data,
    rounds,
    round: atEnd ? nextRound : data.round,
    match: atEnd ? 0 : data.match + 1,
    turn: 0,
    phase: 'ready',
  };
}

function isScore(value: unknown): value is Score {
  return (
    isJsonObject(value) &&
    isNonnegativeSafeInteger(value.moves) &&
    value.moves <= MOVES_MAX &&
    isNonnegativeSafeInteger(value.elapsedMs) &&
    value.elapsedMs <= ELAPSED_MAX_MS
  );
}

export function readTournament(text: string): TournamentData | null {
  const value = text.length <= 1_000_000 ? parseJson(text) : undefined;
  if (
    !isJsonObject(value) ||
    value.version !== 1 ||
    !Array.isArray(value.names) ||
    ![4, 8].includes(value.names.length) ||
    !value.names.every(
      (name: unknown) => typeof name === 'string' && name.trim().length > 0 && name.length <= 100,
    ) ||
    !Array.isArray(value.rounds) ||
    value.rounds.length !== Math.log2(value.names.length) ||
    !isNonnegativeSafeInteger(value.round) ||
    !isNonnegativeSafeInteger(value.match) ||
    (value.turn !== 0 && value.turn !== 1) ||
    !['ready', 'playing', 'turnDone', 'matchDone', 'complete'].includes(String(value.phase)) ||
    !(value.snapshot === null || typeof value.snapshot === 'string')
  )
    return null;
  const names: string[] = value.names;
  const rounds: Match[][] = [];
  for (let r = 0; r < value.rounds.length; r++) {
    const input: unknown = value.rounds[r];
    if (!Array.isArray(input) || input.length !== names.length / 2 ** (r + 1)) return null;
    const round: Match[] = [];
    for (const item of input) {
      if (
        !isJsonObject(item) ||
        !Array.isArray(item.players) ||
        item.players.length !== 2 ||
        !item.players.every(
          (p: unknown) => p === null || (isNonnegativeSafeInteger(p) && p < names.length),
        ) ||
        !Array.isArray(item.scores) ||
        item.scores.length !== 2 ||
        !item.scores.every((s: unknown) => s === null || isScore(s)) ||
        !(
          item.winner === null ||
          (isNonnegativeSafeInteger(item.winner) && item.players.includes(item.winner))
        ) ||
        !(
          item.boardCode === null ||
          (typeof item.boardCode === 'string' && parseBoardCode(item.boardCode))
        )
      )
        return null;
      round.push({
        players: [item.players[0], item.players[1]],
        scores: [item.scores[0], item.scores[1]],
        winner: item.winner,
        boardCode: item.boardCode,
      });
    }
    rounds.push(round);
  }
  const round = value.rounds[value.round];
  if (!Array.isArray(round) || value.match >= round.length) return null;
  const phase = value.phase;
  if (
    phase !== 'ready' &&
    phase !== 'playing' &&
    phase !== 'turnDone' &&
    phase !== 'matchDone' &&
    phase !== 'complete'
  )
    return null;
  const data: TournamentData = {
    version: 1,
    names,
    rounds,
    round: value.round,
    match: value.match,
    turn: value.turn,
    phase,
    snapshot: value.snapshot,
  };
  const match = currentMatch(data);
  if (
    match.players.some((p) => p === null) ||
    (phase === 'playing' && (!match.boardCode || !data.snapshot)) ||
    (phase === 'turnDone' && (!match.scores[0] || data.turn !== 0)) ||
    ((phase === 'matchDone' || phase === 'complete') && match.winner === null)
  )
    return null;
  if (data.snapshot) {
    const game = decodeSnapshot(data.snapshot);
    if (!game || game.boardCode !== match.boardCode || phase !== 'playing') return null;
  }
  return data;
}
